<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowLeft,Download,FileCode2,FolderOpen,Search,ChevronRight,Copy,RefreshCw,Layers,Hash,Clock,BookOpen,X,Sparkles,CheckCircle2} from 'lucide-vue-next'
import {api,post,type Book} from '../api'
import {useStore} from '../store'
import Markdown from '../components/Markdown.vue'
const route=useRoute(),router=useRouter(),store=useStore(),bid=computed(()=>String(route.params.id)),book=ref<Book|null>(null),files=ref<{path:string;chars:number}[]>([]),selected=ref(''),content=ref(''),query=ref(''),results=ref<any[]>([]),error=ref(''),loading=ref(false),raw=ref(false),confirm=ref(false),busy=ref(false),fileLoading=ref(false),includeSource=ref(false),purpose=ref('all')
const visibleFiles=computed(()=>files.value.filter(f=>!query.value||f.path.toLowerCase().includes(query.value.toLowerCase())))
async function load(){loading.value=true;try{book.value=await api('/books/'+bid.value);purpose.value=book.value?.metadata?.purpose||'all';const s=await api('/books/'+bid.value+'/skill');files.value=s.files;const q=String(route.query.file||'SKILL.md');if(files.value.length)await select(files.value.some(f=>f.path===q)?q:files.value[0].path)}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
let sequence=0
async function select(path:string){selected.value=path;fileLoading.value=true;const s=++sequence;try{const f=await api('/books/'+bid.value+'/skill/file?path='+encodeURIComponent(path));if(s===sequence)content.value=f.content}catch(e){error.value=(e as Error).message}finally{if(s===sequence)fileLoading.value=false}}
async function search(){if(!query.value.trim()){results.value=[];return}try{results.value=await api('/books/'+bid.value+'/search?kind=skill&q='+encodeURIComponent(query.value))}catch(e){store.notify((e as Error).message)}}
async function regenerate(){if(!store.config.model){router.push('/settings?return='+encodeURIComponent(route.path));return}busy.value=true;try{await post('/books/'+bid.value+'/generate',{config:store.config,reset:true,purpose:purpose.value});confirm.value=false;router.push('/books/'+bid.value)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function copy(){try{await navigator.clipboard.writeText(content.value);store.notify('已复制 Skill 文件')}catch{store.notify('浏览器不允许访问剪贴板')}}
let searchTimer:ReturnType<typeof setTimeout>|undefined
watch(query,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(search,300)})
onUnmounted(()=>clearTimeout(searchTimer))
onMounted(load);watch(bid,load)
</script>
<template><section class="page skill-page"><RouterLink :to="'/books/'+bid" class="back-link"><ArrowLeft :size="16"/>返回问书</RouterLink><div class="page-heading"><div><div class="eyebrow">THE KNOWLEDGE BEHIND THE ANSWER</div><h1>{{book?.title||'Book'}}<span class="skill-heading-tag">Skill</span></h1><p>看看 AI 从这本书中学到了什么。这份知识，属于你。</p></div><div class="heading-actions"><button class="button" :disabled="!book?.chapterCount||book?.status==='generating'" @click="confirm=true"><RefreshCw :size="16"/>重新生成</button><a v-if="files.length" :href="'/api/books/'+bid+'/export?include_source='+includeSource" class="button primary"><Download :size="16"/>导出 Skill</a></div></div><div v-if="error" class="error-box">{{error}}</div><div v-if="loading" class="loading-block"><RefreshCw class="spin" :size="22"/>正在读取 Skill…</div><div v-else-if="!files.length" class="empty-shelf"><FileCode2 :size="36"/><h3>Skill 还没有生成</h3><p>完成知识蒸馏后，这里会显示结构化知识文件。</p><RouterLink :to="'/books/'+bid" class="button primary">去生成 Skill<ChevronRight :size="16"/></RouterLink></div><template v-else><div class="skill-export-options"><label><input type="checkbox" v-model="includeSource"/>导出时包含原文与完整章节</label><span>默认只导出蒸馏知识；勾选后可导入恢复原文追溯。</span></div><div class="notice" v-if="book?.metadata?.generatorVersion==='book-to-skill-1.0'"><Sparkles :size="17"/><span>新生成器已参考 book-to-skill：可重新生成核心框架、按需章节知识与决策速查表。</span></div><div class="skill-stats"><div><span>核心概念</span><strong>{{book?.stats?.concepts??'—'}}<Hash :size="19"/></strong></div><div><span>实践方法</span><strong>{{book?.stats?.methods??'—'}}<Sparkles :size="19"/></strong></div><div><span>主要论证</span><strong>{{book?.stats?.arguments??'—'}}<Layers :size="19"/></strong></div><div><span>全书章节</span><strong>{{book?.metadata?.chapterCount||book?.stats?.chapters||book?.chapterCount}}<BookOpen :size="19"/></strong></div></div><div class="skill-meta"><span><CheckCircle2 :size="14"/>Skill v{{book?.metadata?.skillVersion||'1.0'}}</span><span>生成器 {{book?.metadata?.generatorVersion||'导入'}}</span><span>模型 {{book?.metadata?.model||'未知'}}</span><span v-if="book?.metadata?.generatedAt"><Clock :size="13"/>{{new Date(book.metadata.generatedAt).toLocaleDateString('zh-CN')}}</span></div><div v-if="book?.metadata?.generatorReference" class="skill-provenance"><a :href="book.metadata.generatorReference.repository" target="_blank" rel="noopener">参考 virgiliojr94/book-to-skill</a><span>规范适配 · {{book.metadata.depth==='reference'?'精简参考':'深入学习'}} · 主文件约 {{book.metadata.quality?.masterTokens||'—'}} Tokens</span></div><div class="skill-browser"><aside class="skill-file-list"><div class="file-root"><FolderOpen :size="17"/>{{book?.metadata?.name||'book-skill'}}</div><form class="file-search" @submit.prevent="search"><Search :size="15"/><input v-model="query" placeholder="搜索 Skill…"/><button v-if="query" class="icon-button" type="button" @click="query='';results=[]" aria-label="清除搜索"><X :size="13"/></button></form><div v-if="results.length" class="skill-search-results"><span>内容匹配</span><button v-for="r in results" :key="r.id" @click="select(r.path)">{{r.path}}<ChevronRight :size="12"/></button></div><button v-for="f in visibleFiles" :key="f.path" class="skill-file-item" :class="{selected:selected===f.path,reference:f.path.startsWith('references/')}" @click="select(f.path)"><FileCode2 :size="15"/><span>{{f.path}}</span></button><p v-if="!visibleFiles.length&&!results.length" class="hint">按 Enter 搜索文件内容</p><div class="file-list-footer">{{files.length}} 个知识文件<br/><span>Markdown · 可移植 · 可复用</span></div></aside><div class="skill-file-content"><header><span><FileCode2 :size="15"/>{{selected}}</span><div><button class="text-link" @click="raw=!raw">{{raw?'阅读视图':'源文件'}}</button><button class="icon-button" @click="copy" title="复制文件"><Copy :size="15"/></button></div></header><div class="file-render"><div v-if="fileLoading" class="loading-block">读取文件…</div><pre v-else-if="raw||selected.endsWith('.json')">{{content}}</pre><Markdown v-else :text="content" :internal-files="true" @navigate="select"/></div></div></div></template></section><div v-if="confirm" class="modal-backdrop"><div class="modal"><h2>重新蒸馏这本书？</h2><p>使用当前 AI 模型重新分析所有章节，将产生 API 用量。成功后替换现有 Skill；生成期间暂时无法问书。</p><label class="purpose-choice">生成用途<select v-model="purpose"><option value="all">综合理解与应用</option><option value="apply">应用作者的框架</option><option value="think">用作者的心智模型思考</option><option value="reference">精简参考与查阅</option></select></label><div class="modal-actions"><button class="button" @click="confirm=false">取消</button><button class="button primary" :disabled="busy" @click="regenerate">开始重新生成</button></div></div></div></template>
